import java.nio.charset.StandardCharsets;

interface Calculator { int calc(int a, int b); }
class Add implements Calculator { public int calc(int a, int b) { return a + b; } }
class Sub implements Calculator { public int calc(int a, int b) { return a - b; } }
public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        String[] p = input.split("\\s+");
        Calculator c = p[0].equals("add") ? new Add() : new Sub();
        System.out.println(c.calc(Integer.parseInt(p[1]), Integer.parseInt(p[2])));
    }
}
